{
  "packet_id": "H6-T02-1",
  "claim_id": "C027",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C027",
    "value": "A revision may be classified good only when prespecified evidence supports the acceptable range.",
    "scope": "Necessary evidence condition for goodness; the acceptable range is not numerically defined.",
    "provenance": {
      "refs": [
        {
          "source_id": "P017",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P017 directly states the necessary evidence condition for classifying a revision as good."
    }
  },
  "signal_basis": {
    "component_id": "C027_SIGNAL",
    "value": "Revision-level export counts, the fraction exceeding one hour and its uncertainty provide the evidence for classification. Prespecified criteria distinguish acceptable, elevated and inconclusive results, with a replication and repeated-testing rule to control accumulated error.",
    "scope": "Classification uses recorded workload and load and criteria defined before testing. An outcome stopped before one hour remains unknown and cannot count as fast.",
    "provenance": {
      "refs": [
        {
          "source_id": "P004",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P019",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the prespecified criteria, measured evidence, classification rule, repeated-testing safeguard and treatment of incomplete outcomes."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C027_EMPIRICAL_RELATION",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported as a necessary classification condition; no unresolved empirical relation is needed."
    }
  },
  "rationale": "The claim restricts when the procedure may label a revision good. The described evidence and classification rule license that restriction within its stated bounds. It neither declares any particular revision good nor guarantees its underlying tail rate.",
  "uncertainty": "The acceptable range and confidence criteria have no numerical values in the packet. This prevents a concrete classification but does not undermine the stated necessary condition.",
  "anomalies": []
}
